domain-overview-missing-domain.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_INVALID_USAGE",
    "message": "Missing required argument: <domain>."
  },
  "agent_guidance": "Pass a domain such as example.com. A full URL also works; only its host is used."
}

domain-overview-no-key.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_AUTH_REQUIRED",
    "message": "No Outrank API key is configured."
  },
  "agent_guidance": "Run `outrank-cli auth login <api-key>` to store a key locally, or set OUTRANK_API_KEY in the environment before retrying."
}

domain-overview-network-error.stdout:
{
  "ok": false,
  "error": {
    "code": "CLI_NETWORK_ERROR",
    "message": "Request failed: fetch failed",
    "details": {
      "outcome_unknown": true,
      "long_running": false
    }
  },
  "agent_guidance": "The connection to https://www.outrank.so failed after the request may have been sent, so its outcome is unknown: the change may have been applied. Inspect the current state with a read command before repeating it."
}

